#requires -Version 5.1
[CmdletBinding()]param([int]$Hours=48,[int]$MaxEvents=500)
$root='C:\ProgramData\BlueRidge\EventTriage';$logs='C:\ProgramData\BlueRidge\Logs';New-Item -ItemType Directory -Force -Path $root,$logs|Out-Null;$s=Get-Date -Format yyyyMMdd-HHmmss;$d=Join-Path $root "events-$env:COMPUTERNAME-$s";New-Item -ItemType Directory -Force -Path $d|Out-Null;Start-Transcript -Path (Join-Path $logs 'event-log-triage.log') -Append|Out-Null
try{$start=(Get-Date).AddHours(-$Hours);$events=foreach($name in 'System','Application'){Get-WinEvent -FilterHashtable @{LogName=$name;StartTime=$start;Level=1,2,3} -ErrorAction SilentlyContinue|Select -First $MaxEvents @{n='Log';e={$name}},TimeCreated,Id,LevelDisplayName,ProviderName,Message};$events|Export-Csv (Join-Path $d events.csv) -NoTypeInformation -Encoding UTF8;$events|Group ProviderName,Id|Sort Count -Descending|Select -First 40 Count,Name|Export-Csv (Join-Path $d top-patterns.csv) -NoTypeInformation;$events|Group LevelDisplayName|Select Name,Count|Export-Csv (Join-Path $d severity-summary.csv) -NoTypeInformation;Write-Host "Event triage bundle: $d" -ForegroundColor Green}finally{Stop-Transcript|Out-Null}
